// Prayer Request — SPX calls update(), play(), stop(), next().

// Write one field value into its element. Operator text is always plain text, never HTML.
function setFieldValue(el, value) {
  if (el.tagName === 'IMG') {
    if (value) { el.src = value; el.style.display = ''; }
    else { el.removeAttribute('src'); el.style.display = 'none'; }
  } else {
    el.textContent = value == null ? '' : String(value);
  }
}

// update(data): field values as JSON, e.g. {"f1":"…","f2":"Gia đình Nguyễn"}. Writes each value,
// then closes the attribution line around what is there and fits the request to the card.
function update(data) {
  var fields = (typeof data === 'string') ? JSON.parse(data) : data;
  for (var key in fields) {
    var el = document.getElementById(key);
    if (el) setFieldValue(el, fields[key]);
  }
  audienceAttribution();
  fitRequest();
}

// play(): take the card on air.
function play() {
  gsap.killTweensOf('*');
  audienceAttribution();
  fitRequest();
  buildInTimeline();
}

// stop(): take the card off air.
function stop() {
  gsap.killTweensOf('*');
  buildOutTimeline();
}

// next(): SPX Continue — advance one step along the default path.
function next() {
  return (typeof revealNextStep === 'function') ? revealNextStep() : null;
}

EOF
cat > /tmp/tail.js <<'EOF'


// ---- Attribution: who sent it, and where ----

function audienceText(id) {
  var el = document.getElementById(id);
  return el ? (el.textContent || '').replace(/^\s+|\s+$/g, '') : '';
}

// Mark the root when the name or the place is empty, so the CSS closes the line up: no stray
// dot, no empty row, and nothing at all under the request when both are empty.
function audienceAttribution() {
  var root = document.querySelector('.audience');
  if (!root) return;
  root.classList.toggle('audience-no-asker', audienceText('f2') === '');
  root.classList.toggle('audience-no-source', audienceText('f3') === '');
}

// ---- The request's size ladder ----
// Families write at length. Rather than cut a request off, the type steps down gently as it
// grows: each rung is a share of the design size and the most lines the request may take at it.
// The last rung (22px at the default scale) still reads comfortably on a stream; only past six
// lines there is the request held with an ellipsis, and the operator panel is told.
var REQUEST_LADDER = [
  { share: 1.00, lines: 3 },
  { share: 0.88, lines: 4 },
  { share: 0.76, lines: 5 },
  { share: 0.66, lines: 6 }
];
var requestOverflow = false;

function fitRequest() {
  var el = document.getElementById('f1');
  if (!el) return;
  el.classList.remove('audience-clamped');
  el.style.fontSize = '';
  var design = parseFloat(window.getComputedStyle(el).fontSize);
  if (!design) return;
  requestOverflow = false;
  for (var i = 0; i < REQUEST_LADDER.length; i++) {
    var rung = REQUEST_LADDER[i];
    var size = design * rung.share;
    el.style.fontSize = size + 'px';
    var lineH = parseFloat(window.getComputedStyle(el).lineHeight) || size * 1.36;
    var lines = Math.round(el.scrollHeight / lineH);
    if (lines <= rung.lines) return;
  }
  el.classList.add('audience-clamped');
  requestOverflow = true;
}

// The control panel asks which values did not fit, so the operator can shorten them.
function noacgTextOverflow() {
  return requestOverflow ? ['f1'] : [];
}

// Read the card once the DOM is in, and again once the bundled face has arrived (the fallback
// face wraps differently).
function audienceReady() { audienceAttribution(); fitRequest(); }
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', audienceReady);
} else {
  audienceReady();
}
if (document.fonts && document.fonts.ready && document.fonts.ready.then) {
  document.fonts.ready.then(audienceReady);
}
EOF
